float box(in vec2 p, in vec2 b){
    vec2 d = abs(p)-b;
    return length(max(d,0.)) + min(max(d.x,d.y),0.);
}
float smoothBox(vec2 st, vec2 w){
    float bArea = 1.-step(0.,box(st,w+vec2(0.1,2.))),
    bSmooth = 1.-smoothstep(0.,.2,box(st,w-vec2(0.045,.1)));
    return bArea * bSmooth;
}
float random(in vec2 st) { return fract(sin(dot(st.xy, vec2(12.9898,78.233)))* 43758.5453123);}
// Value noise by Inigo Quilez - iq/2013 https://www.shadertoy.com/view/lsf3WH
float noise(vec2 st) {
    //st += iTime*0.25;
    vec2 i = floor(st);
    vec2 f = fract(st);
    vec2 u = f*f*(3.0-2.0*f);
    return mix( mix( random( i + vec2(0.0,0.0) ),
                     random( i + vec2(1.0,0.0) ), u.x),
                mix( random( i + vec2(0.0,1.0) ),
                     random( i + vec2(1.0,1.0) ), u.x), u.y);
}
// nako's function https://www.shadertoy.com/view/slcBDB
float noisePaint(vec2 st){
    float n1 = noise(st*5.),
    n2 = noise(st*350.),
    n3 = noise(st*150.),
    n4 = noise(st*57.);
    return (n1+n2+n3)/6.+n4*.5;
}
float drawPaint(vec2 st, vec2 w, float wO, float strokeGranularity, float strokeWeight){
    float b = smoothBox(st,w*wO),
    bO = smoothBox(st,w)-b,
    p = smoothstep(.3,1.,b+bO*noisePaint(st*vec2(.1*strokeGranularity,.1))),
    oP = smoothstep(.1,1.,(b+bO)*noise(st*strokeWeight));
    return mix(p, oP, .4);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 R = iResolution.xy,
    st = (fragCoord*2.-R.xy)/R.y;

    vec3 RED_1 = vec3(169, 1, 0)/255.;
    vec3 RED_2 = vec3(143, 1, 0)/255.;
    vec3 YELLOW = vec3(243, 185, 111)/255.;

    vec3 col = vec3(.2,.1,.02) * min(1.,noise(st*12.)*.4+.6);  // bg w/ noise

    vec2 o = vec2(.75,0.),
    w = vec2(.3,.9);
    col += drawPaint(st-o,w,0.7,1.5,2.) * YELLOW;
    col += drawPaint(st,w,0.8,3.,-5.) * RED_2;
    col += drawPaint(st+o,w,0.9,10.,3.) * RED_1;

    fragColor = vec4(col,1.);
}
